import React, { useState, useEffect } from "react";
import ChartistGraph from "react-chartist";
import {
  Badge,
  Card,
  Table,
  Container,
  Row,
  Col,
  Modal, // เพิ่ม Modal
  Button
} from "react-bootstrap";

function Dashboard() {
  const [tableData, setTableData] = useState([]);
  const [chartData, setChartData] = useState({ labels: [], series: [] });
  const [stats, setStats] = useState({ busStops: 0, cameras: "Active", alerts: 0, users: 0 });

  // --- ส่วนที่เพิ่มใหม่: State สำหรับ Modal และการเลือกสถานี ---
  const [showModal, setShowModal] = useState(false);
  const [selectedStation, setSelectedStation] = useState(null);

  const handleRowClick = (station) => {
    setSelectedStation(station); // เก็บข้อมูลสถานีที่คลิก
    setShowModal(true);          // เปิด Modal
  };

  const fetchData = async () => {
    try {
      const statsRes = await fetch('http://localhost:3000/api/dashboard-stats');
      const statsJson = await statsRes.json();
      setStats({
        busStops: statsJson.capacity,
        cameras: statsJson.revenue,
        alerts: statsJson.errors,
        users: statsJson.followers
      });

      const tableRes = await fetch('http://localhost:3000/api/table-data');
      const tableJson = await tableRes.json();
      setTableData(tableJson);

      const chartRes = await fetch('http://localhost:3000/api/chart-data');
      const chartJson = await chartRes.json();
      setChartData(chartJson);
    } catch (err) {
      console.error("Fetch Error:", err);
    }
  };

  useEffect(() => {
    fetchData();
    const interval = setInterval(fetchData, 30000);
    return () => clearInterval(interval);
  }, []);

  return (
    <Container fluid>
      {/* ส่วนการ์ดและกราฟ (คงเดิมเหมือนโค้ดก่อนหน้า) */}
      <Row>
          {/* ... การ์ดสถิติ 4 ใบ ... */}
      </Row>

      <Row>
        <Col md="12">
          <Card className="strpied-tabled-with-hover">
            <Card.Header>
              <Card.Title as="h4">Bus Stop Detail Table</Card.Title>
              <p className="card-category">คลิกที่แถวเพื่อดูรายละเอียดกล้อง CCTV</p>
            </Card.Header>
            <Card.Body className="table-full-width table-responsive px-0">
              <Table className="table-hover table-striped">
                <thead>
                  <tr>
                    <th className="border-0">ID</th>
                    <th className="border-0">Station Name</th>
                    <th className="border-0">Passenger</th>
                    <th className="border-0">Status</th>
                    <th className="border-0">Action</th>
                  </tr>
                </thead>
                <tbody>
                  {tableData.map((item, index) => (
                    <tr 
                      key={item.id || index} 
                      onClick={() => handleRowClick(item)} 
                      style={{ cursor: 'pointer' }} // เปลี่ยน cursor เป็นรูปมือ
                    >
                      <td>{item.id}</td>
                      <td>{item.stationName}</td>
                      <td>{item.passengerCount}</td>
                      <td>
                        <Badge bg={item.status === "Crowded" ? "danger" : "success"}>
                          {item.status}
                        </Badge>
                      </td>
                      <td>
                        <Button variant="info" size="sm">View Cameras</Button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </Table>
            </Card.Body>
          </Card>
        </Col>
      </Row>

      {/* --- ส่วนที่เพิ่มใหม่: Modal สำหรับแสดงรายละเอียดกล้อง --- */}
      <Modal 
        show={showModal} 
        onHide={() => setShowModal(false)}
        size="lg"
        centered
      >
        <Modal.Header closeButton>
          <Modal.Title>
            Station Details: {selectedStation?.stationName}
          </Modal.Title>
        </Modal.Header>
        <Modal.Body>
          <h5>CCTV Camera Feeds</h5>
          <p className="text-muted">รายการกล้องที่ติดตั้งในบริเวณนี้</p>

          <Table bordered hover>
            <thead className="bg-light">
              <tr>
                <th>Camera Name</th>
                <th>IP Address</th>
                <th>Status</th>
                <th>Last Activity</th>
              </tr>
            </thead>
            <tbody>
              {/* ตรงนี้ในอนาคตสามารถ map ข้อมูลกล้องจริงที่มาจาก API ได้ */}
              <tr>
                <td>CCTV-01 (Entrance)</td>
                <td>192.168.1.101</td>
                <td><Badge bg="success">Online</Badge></td>
                <td>{selectedStation?.lastUpdated}</td>
              </tr>
              <tr>
                <td>CCTV-02 (Platform)</td>
                <td>192.168.1.102</td>
                <td><Badge bg="success">Online</Badge></td>
                <td>{selectedStation?.lastUpdated}</td>
              </tr>
            </tbody>
          </Table>

          <div className="mt-4 bg-dark text-white d-flex align-items-center justify-content-center" style={{ height: '200px', borderRadius: '8px' }}>
            <p><i className="nc-icon nc-zoom-split mr-2"></i> [ Live Feed Simulation for {selectedStation?.stationName} ]</p>
          </div>
        </Modal.Body>
        <Modal.Footer>
          <Button variant="secondary" onClick={() => setShowModal(false)}>
            Close
          </Button>
        </Modal.Footer>
      </Modal>

    </Container>
  );
}

export default Dashboard;
